/* Hand-authored, NOT generated by ng-openapi-gen — see search-request.ts. */

import { MonetaryAmount } from '../models/monetary-amount';

/**
 * One hit from `POST /api/search`: a matched document with its relevance
 * `score` and a `snippet` of the matched text. The `id` points at a real
 * document — the UI links each card to `/documents/{id}`.
 */
export interface SearchResult {

  /** Id of the matched document (links to its detail page). */
  id: string;

  /** Relevance score for this hit; higher is a better match. */
  score: number;

  /** Highlighted excerpt of the matched text, for display on the card. */
  snippet?: string;

  /**
   * The matched document's type, when the backend includes it — used only to
   * label the card, never to recompute anything.
   */
  type?: string;

  /** The matched document's total, when the backend includes it. */
  total?: MonetaryAmount;

  /** Currency code the {@link total} is in (drives money formatting). */
  currency?: string;
}
